 const growth=E('section',{class:'overview-project'},E('h2',{},'システム自身の改善'),E('p',{},g.enabled?'作業コピーでの自律改善が有効です。':'自律改善の実行設定は無効です。'),E('p',{},g.scope||'登録コードの作業コピーで検証します。'));
