 wrap.append(growth);
 const usage=state.data.token_usage||{},usageBox=E('section',{class:'overview-project'},E('h2',{},'AI使用量'),E('p',{},usage.scope||'使用量の記録は未取得です。'),E('p',{},'記録あり '+(usage.observed_requests||0)+'依頼 / 使用量未取得 '+(usage.unknown_requests||0)+'依頼'));
